  examplesTitle: 'Ví dụ có sẵn để mở',
  examplesIntro: 'Mỗi dự án mở ra đầy đủ và được thiết kế bằng F5. Dùng chúng để làm quen với ứng dụng hoặc làm điểm xuất phát.',
  examples: [
    SiteExample('orchard', 'Vườn cây ăn quả', 'Phun mưa cục bộ trên cam quýt và nhỏ giọt trên nho, giếng có bơm và bộ lọc, đất dốc.'),
