    SiteExample('sportsField', 'Sân bóng đá', 'Sân tiêu chuẩn 105 × 68 m với béc phun va đập bố trí năm hàng, bể chứa, máy bơm và ca tưới ban đêm.'),
    SiteExample('rowCrop', 'Cây trồng hàng tưới nhỏ giọt', 'Bốn lô cà chua dùng dây tưới nhỏ giọt, ống nhánh có van, lọc lưới, máy bơm và đất dốc.'),
    SiteExample('pivot', 'Pivot trung tâm', 'Pivot 300 m trên ngô cấp nước từ ống chính, giếng và máy bơm; báo cáo tháp, nhịp và vòi phun.'),
